{
  "technical_and_design_decisions": [
    "Use Go modules to import the externalized packages directly from the main Hyperledger Fabric repository.",
    "Refactor the Fabric Go SDK to remove the 'internal/github.com/hyperledger/fabric' and 'third_party/github.com/hyperledger/fabric' directories.",
    "Ensure backward compatibility where possible, or provide clear migration paths for SDK users if breaking changes are unavoidable.",
    "For U6, implement a temporary configuration flag to enable the go.mod chaincode package workaround, ensuring it can be easily deprecated and removed later."
  ],
  "assumptions": [
    "The externalized packages in the main Hyperledger Fabric repository are stable and provide the necessary APIs required by the SDK.",
    "The developer is familiar with both the Fabric Go SDK and the main Hyperledger Fabric codebase.",
    "Existing unit and integration tests in the SDK are sufficient to verify the changes, requiring only minor additions for new behavior.",
    "The temporary workaround for U6 will be clearly marked as deprecated from the start to discourage long-term use."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Analysis and Design",
      "activity_description": "Review the current copied code in the SDK, identify the externalized packages in the main Fabric repo, and plan the migration strategy for all components.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Externalize gossip utilities (U1)",
      "activity_description": "Replace the modified version of the discovery client and gossip utilities protoext with the externalized copy from the main Fabric repository.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "Externalize cauthdsl utilities (U2)",
      "activity_description": "Replace the copied cauthdsl utilities with the externalized common components from the main Fabric repository.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize ccprovider structures (U3)",
      "activity_description": "Replace the copied ccprovider structures with the externalized common components from the main Fabric repository.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize ledger structures (U4)",
      "activity_description": "Replace the copied ledger structures with the externalized common components from the main Fabric repository.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize common utilities (U5)",
      "activity_description": "Replace the modified version of common utilities (common and core) with the externalized copy from the main Fabric repository.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement go.mod chaincode workaround (U6)",
      "activity_description": "Implement a temporary workaround to honor go.mod files that are part of a chaincode package during the transition to modules.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A8",
      "activity_name": "Externalize configtxgen functions (U7)",
      "activity_description": "Replace the modified version of configtxgen functions with the externalized copy from the main Fabric repository.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A9",
      "activity_name": "Externalize configtxlator functions (U8)",
      "activity_description": "Replace the modified version of configtxlator functions with the externalized copy from the main Fabric repository.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Testing and Integration",
      "activity_description": "Run unit and integration tests to ensure the SDK works correctly with the externalized packages and the temporary workaround. Fix any breaking changes.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation and Cleanup",
      "activity_description": "Remove old copied code directories, update SDK documentation, and add deprecation notices for the temporary go.mod workaround.",
      "most_likely_effort": 6
    }
  ],
